package com.cpf.education.online.externalsideeffect.service;
import com.cpf.core.api.result.*; import com.cpf.data.persistence.api.CpfCrudRepository; import com.cpf.data.persistence.api.annotation.CpfTransactional; import com.cpf.education.online.externalsideeffect.client.PaymentInstitutionClient; import com.cpf.education.online.externalsideeffect.dto.PaymentCommand; import com.cpf.education.online.externalsideeffect.recovery.PaymentReconcileService; import com.cpf.education.online.externalsideeffect.repository.PaymentState; import com.cpf.foundation.annotation.CpfService; import org.springframework.beans.factory.ObjectProvider;
/** PaymentService는 외부 Side Effect와 Local DB Commit 결과를 분리하고 UNKNOWN을 복구로 연결하는 거래 Golden Path입니다. */
@CpfService public class PaymentService {private final PaymentInstitutionClient client;private final PaymentReconcileService reconcile;private final ObjectProvider<CpfCrudRepository<PaymentState,String>> repositories;public PaymentService(PaymentInstitutionClient client,PaymentReconcileService reconcile,ObjectProvider<CpfCrudRepository<PaymentState,String>> repositories){this.client=client;this.reconcile=reconcile;this.repositories=repositories;}
 @CpfTransactional public CpfResult<String> pay(PaymentCommand c){repository().save(new PaymentState(c.idempotencyKey(),"PENDING",null));CpfResult<String> r=client.pay(c);if(r.isSuccess()){repository().save(new PaymentState(c.idempotencyKey(),"COMPLETED",r.data()));return r;}if(r.isUnknown()){repository().save(new PaymentState(c.idempotencyKey(),"UNKNOWN","payment:"+c.idempotencyKey()));return CpfResult.unknown(r.errorCode(),r.errorMessage(),reconcile.recovery(c.idempotencyKey()));}throw new IllegalStateException("확정 실패는 transaction rollback rule에 따라 처리합니다: "+r.status());}
 private CpfCrudRepository<PaymentState,String> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF payment repository is not configured");return r;} }
